def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_opponents += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (25.0 - float(supply)) / 10.0
    scarcity = max(0.0, min(1.0, scarcity))

    base = 24.0 + 10.0 * scarcity

    if highest_prev >= 120:
        base -= 6.0
    elif highest_prev >= 90:
        base -= 2.0
    elif highest_prev >= 50:
        base += 4.0
    else:
        base += 8.0

    base += min(urgent_opponents, 3) * 4.0
    base += min(rich_opponents, 3) * 2.0

    if hp <= 2:
        bid = max(base, 92.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(base, 68.0 + 8.0 * scarcity)
    elif hp >= 8 and no_water_days == 0 and highest_prev >= 95:
        bid = min(base, 26.0)
    else:
        bid = base

    if day >= 8:
        bid += 8.0
    if day >= 9 and hp <= 5:
        bid += 12.0

    reserve = max(0.0, (10 - int(day)) * 8.0)
    max_affordable = max(0.0, budget - reserve)
    if hp <= 3:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    prev_bid_by_agent = {}
    for agent_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                b = None
        if b is not None:
            prev_bids.append(b)
            prev_bid_by_agent[agent_id] = b

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Estimate how aggressive the field was yesterday
    # If someone was near our daily salary, they likely fought for water; we match moderately.
    pressure = 0.0
    if prev_bids:
        pressure = highest_prev_bid

    # Supply pressure: when supply is low, bids should be higher.
    # For our fixed WATER_REQ=9, supply range 15..25 implies scarcity varies.
    scarcity = 0.0
    if supply <= float(MIN_SUPPLY):
        scarcity = 1.0
    elif supply >= float(MAX_SUPPLY):
        scarcity = 0.0
    else:
        scarcity = (float(MAX_SUPPLY) - supply) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))

    # Base bid: target the lower band that kept Alex/Eric alive while avoiding Cindy's high spending.
    # Use hp/no_water_days to decide whether to escalate.
    # If we are in danger, bid more; otherwise keep moderate.
    risk = 0.0
    if hp <= 2.0:
        risk = 1.0
    elif hp <= 4.0:
        risk = 0.6
    else:
        risk = 0.2
    if no_water_days >= 2:
        risk = max(risk, 0.7)

    # Determine target bid using yesterday pressure and scarcity.
    # If yesterday highest bid was high, we raise slightly but not to Cindy-level.
    # Otherwise, keep near ~0.55*DAILY_SALARY (Eric/Alex band) adjusted by scarcity.
    baseline = DAILY_SALARY * 0.55
    if pressure >= DAILY_SALARY * 1.25:
        target = baseline + DAILY_SALARY * 0.15 * scarcity + DAILY_SALARY * 0.10 * risk
    elif pressure >= DAILY_SALARY * 0.95:
        target = baseline + DAILY_SALARY * 0.10 * scarcity + DAILY_SALARY * 0.07 * risk
    else:
        target = baseline + DAILY_SALARY * 0.08 * scarcity + DAILY_SALARY * 0.05 * risk

    # If our hp is very low, we must secure water: bid closer to daily salary.
    if hp <= 2.0:
        target = max(target, DAILY_SALARY * 0.85)
    elif hp <= 3.0:
        target = max(target, DAILY_SALARY * 0.65)

    # Never exceed budget; also keep a ceiling to avoid waste.
    ceiling = min(budget, DAILY_SALARY * (1.0 + 0.25 * scarcity))
    bid = min(target, ceiling)

    # Ensure non-negative and at least a tiny bid if budget allows
    if bid < 0.0:
        bid = 0.0
    if bid == 0.0 and budget > 0.0:
        bid = min(budget, 1.0)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    base_bid_value = DAILY_SALARY * 0.6

    highest_prev_bid = 0.0
    previous_bids_exist = False
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])
            previous_bids_exist = True

    if not previous_bids_exist:
        highest_prev_bid = base_bid_value 

    available_funds = my_status['budget'] + DAILY_SALARY

    my_bid = 0.0
    current_day = day_context['day']

    hp_factor = 1.0
    day_factor = 1.0

    if my_status['hp'] <= 2: 
        hp_factor = 1.3
    elif my_status['hp'] <= 5: 
        hp_factor = 1.15
    elif my_status['hp'] <= 8: 
        hp_factor = 1.0
    else: 
        hp_factor = 0.85

    if current_day >= EPISODE_DAYS - 2: 
        day_factor = 1.2
    elif current_day >= EPISODE_DAYS - 4: 
        day_factor = 1.1

    if highest_prev_bid > DAILY_SALARY * 0.8: 
        my_bid = highest_prev_bid + (DAILY_SALARY * 0.05 * hp_factor * day_factor)
    elif highest_prev_bid > DAILY_SALARY * 0.5: 
        my_bid = highest_prev_bid + (DAILY_SALARY * 0.02 * hp_factor * day_factor)
    else: 
        my_bid = base_bid_value * hp_factor * day_factor

    my_bid = max(my_bid, DAILY_SALARY * 0.3)

    if num_alive_opponents == 0:
        my_bid = DAILY_SALARY * 0.1

    my_bid = min(my_bid, available_funds)
    my_bid = max(0.0, my_bid)

    return float(my_bid)

